from pathlib import Path
import base64, json
R=Path(__file__).resolve().parents[2]
OUT=R/"renders/temple_reseau_strict_v1"
REF=R/"source/temple_reseau_strict_v1/references/reference.png"
m=json.loads((OUT/"manifest.json").read_text())
def uri(p): return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={e["id"]:{**e, "images":{n:uri(OUT/e["id"]/(n+".png")) for n in e["layers"]}, "schema":uri(OUT/e["id"]/"schema.png"), "composition":uri(OUT/e["id"]/"composition.png")} for e in m["rooms"]}
ref_uri=uri(REF)
planche_uri=uri(OUT/"PLANCHE.png")
h=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Temple STRICT — même DA/texture que référence</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#0f0e1a;color:#e8e0ff;font:16px system-ui}}header,main,footer{{max-width:1260px;margin:auto;padding:24px}}h1{{font-size:28px;margin:8px 0}}p{{color:#c8bed6;line-height:1.6}}.tag{{font-size:12px;letter-spacing:2px;color:#b8a0f0}}.toolbar{{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}}select,button{{padding:12px;border:1px solid #8a6ab8;border-radius:6px;background:#2a2340;color:#f0e8ff}}.layout{{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px}}canvas{{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#161320}}aside{{background:#261f3a;padding:18px;border-radius:8px}}label{{display:block;margin:15px 0;font-size:14px}}a{{color:#d6c0ff}}small{{color:#bdb0d6}}footer{{border-top:1px solid #4d3d68}}@media(max-width:780px){{.layout{{grid-template-columns:1fr}}}}</style><header><div class="tag">TEMPLE STRICT / MÊME MATIÈRE / PERSPECTIVE CONSERVÉE</div><h1>Réseau temple — sampling strict de IMG_5004</h1><p><b>Même DA, même textures, même perspective caméra, même bordure rocheuse que la référence 408×408.</b> 6 pièces 512×512 en <b>quilt sampling 8px sans recoloration/rotation/échelle</b> — dalles claires, murs violets ornés et roche brune sont les <b>pixels natifs</b> de ta map. Layout adapté (ports 64px) mais <b>matière identique</b>.</p><p><small>Référence affichée à l’échelle · 6 pièces · 47 calques · 15 ports · patches natifs vérifiés · DA préservée</small></p></header><main><div class="toolbar"><select id="room"></select><button id="plan">Voir schéma</button><button id="reference">Voir référence 408×408</button><button id="export">Exporter PNG</button></div><div class="layout"><section><canvas id="view" width="512" height="512"></canvas><p id="status"></p></section><aside><b>Calques 512×512</b><div id="layers"></div><small>Sol = dalles (140,200), Murs = violets (80,24), Roche = brune (12,40), Dirt = terre (152,340). Autel/piliers copiés direct. Tous les calques sont des découpes natives, pas des redessins.</small></aside></div><p><img src="{planche_uri}" style="width:100%;image-rendering:pixelated;border:1px solid #4d3d68"></p><p><b>Matériaux natifs</b> — patches de référence vérifiés SHA256, utilisés tels quels en quilting avec seam 8px.</p></main><footer><p>Source : <b>IMG_5004.png 408×408</b> — autel + colonnes + dalles. Méthode : <b>quilt sampling</b> 24×24 (dirt 24×16) avec overlap 8px et seam minimal, sans lissage. Tuiles originales x2 max, jamais étirées.</p><small>15 ports 64px : bande commune issue du patch sol natif, opaque et identique. Vérif : recomposition, calques 512, ports opaques. Pas de test PMDO/collision.</small></footer><script>const DATA={json.dumps(data)},REF="{ref_uri}",c=document.getElementById("view"),ctx=c.getContext("2d"),select=document.getElementById("room");let entry,images={{}},visible={{}},schema=false,reference=false;function image(src){{let im=new Image();im.src=src;return im}}const ref=image(REF);function download(src,name){{let a=document.createElement("a");a.href=src;a.download=name;a.click()}}for(const [id,e] of Object.entries(DATA)){{let o=document.createElement("option");o.value=id;o.textContent=e.title;select.append(o)}}select.value="salle_traversee";function setup(){{entry=DATA[select.value];images={{}};visible={{}};const root=document.getElementById("layers");root.innerHTML="";for(const n of entry.layers){{images[n]=image(entry.images[n]);visible[n]=true;const l=document.createElement("label"),ch=document.createElement("input"),a=document.createElement("a");ch.type="checkbox";ch.checked=true;ch.onchange=()=>visible[n]=ch.checked;a.href=entry.images[n];a.download=entry.id+"_"+n+".png";a.textContent=" ↓";l.append(ch,document.createTextNode(n.replace(/^\\d+[a-z]*_/,"").replaceAll("_"," ")),a);root.append(l)}}images.schema=image(entry.schema);document.getElementById("status").textContent=entry.title+" · Accès : "+entry.ports.map(p=>p.direction).join(" / ")}}select.onchange=setup;document.getElementById("plan").onclick=e=>{{schema=!schema;reference=false;e.target.textContent=schema?"Voir rendu":"Voir schéma"}};document.getElementById("reference").onclick=e=>{{reference=!reference;e.target.textContent=reference?"Revenir":"Voir référence"}};document.getElementById("export").onclick=()=>download(c.toDataURL(),reference?"reference.png":entry.id+(schema?"_schema":"")+".png");function draw(im){{if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0)}}function render(){{const w=reference?408:512,h=reference?408:512;if(c.width!==w||c.height!==h){{c.width=w;c.height=h}}ctx.clearRect(0,0,c.width,c.height);if(reference)draw(ref);else if(schema)draw(images.schema);else for(const n of entry.layers)if(visible[n])draw(images[n]);requestAnimationFrame(render)}}setup();requestAnimationFrame(render);</script></html>'''
(R/"apercu_temple_reseau_strict_v1.html").write_text(h, encoding="utf8")
print("gallery -> apercu_temple_reseau_strict_v1.html", len(h))
